/**
 * jsi-rs demo app
 *
 * Two Rust integration generations are on screen at once:
 * - `RustDemo` (top): a legacy `#[host_object]` global installed directly
 *   into the JS scope by the original jsi-rs pattern.
 * - `TurboDemo` (bottom): a `#[RustTurboModule]` module. The import below
 *   is TypeScript *generated by the Rust macro* at compile time
 *   (native/jsi-demo-module/generated/rust-turbo/) — requesting it
 *   bootstraps the `RustTurbo` proxy, which lazily constructs the module.
 *
 * @format
 */

import React, {useEffect, useState} from 'react';
import {SafeAreaView, ScrollView, StatusBar, StyleSheet, Text, View} from 'react-native';

// generated by #[RustTurboModule("TurboDemo")] in native/jsi-demo-module —
// importing it triggers the native bindings installer on first use
import {getTurboDemo} from './native/jsi-demo-module/generated/rust-turbo/TurboDemo';

declare global {
  var RustDemo:
    | {
        add(a: number, b: number): number;
        greet(name: string): string;
        sumList(nums: number[]): number;
        makePoint(x: number, y: number, label: string): {x: number; y: number; label: string};
        pointMagnitude(p: {x: number; y: number}): number;
        readonly version: string;
      }
    | undefined;
}

function computeResults(rust: NonNullable<typeof RustDemo>): Array<[string, string]> {
  const out: Array<[string, string]> = [];

  out.push(['RustDemo.version', rust.version]);
  out.push(['RustDemo.add(19, 23)', String(rust.add(19, 23))]);
  out.push(['RustDemo.greet("jsi-rs")', rust.greet('jsi-rs')]);
  out.push(['RustDemo.sumList([1..100])', String(rust.sumList(Array.from({length: 100}, (_, i) => i + 1)))]);

  const p = rust.makePoint(3, 4, 'demo point');
  out.push(['RustDemo.makePoint(3, 4, ...)', JSON.stringify(p)]);
  out.push(['RustDemo.pointMagnitude(p)', String(rust.pointMagnitude(p))]);

  return out;
}

function App(): React.JSX.Element {
  const rust = globalThis.RustDemo;

  const [turboResults, setTurboResults] = useState<Array<[string, string]>>([]);
  const [turboError, setTurboError] = useState<string | null>(null);

  // TurboDemo calls, including an async one (a JS Promise backed by the
  // jsi-turbo worker pool)
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const turbo = getTurboDemo();
        const p = turbo.makePoint('turbo point', 6, 8);
        const rows: Array<[string, string]> = [
          ['TurboDemo.version', turbo.version],
          ['TurboDemo.add(19, 23)', String(turbo.add(19, 23))],
          ['TurboDemo.greet("turbo")', turbo.greet('turbo')],
          ['TurboDemo.makePoint(6, 8, ...)', JSON.stringify(p)],
          ['TurboDemo.pointMagnitude(p)', String(turbo.pointMagnitude(p))],
          ['await TurboDemo.slowAdd(20, 22)', String(await turbo.slowAdd(20, 22))],
        ];
        if (!cancelled) {
          setTurboResults(rows);
        }
      } catch (e) {
        if (!cancelled) {
          setTurboError(String(e));
        }
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <SafeAreaView style={styles.background}>
      <StatusBar barStyle="dark-content" />
      <ScrollView contentInsetAdjustmentBehavior="automatic" style={styles.background}>
        <View style={styles.container}>
          <Text style={styles.title}>jsi-rs demo</Text>

          {rust === undefined ? (
            <Text style={styles.error}>
              The Rust module was not installed: the `RustDemo` global does not exist.
            </Text>
          ) : (
            <>
              <Text style={styles.subtitle}>legacy #[host_object] global</Text>
              {computeResults(rust).map(([label, value]) => (
                <View key={label} style={styles.row}>
                  <Text style={styles.label}>{label}</Text>
                  <Text style={styles.value}>{value}</Text>
                </View>
              ))}
            </>
          )}

          <Text style={styles.subtitleTop}>#[RustTurboModule] via generated TS bindings</Text>
          {turboError !== null ? (
            <Text style={styles.error}>TurboDemo failed: {turboError}</Text>
          ) : turboResults.length === 0 ? (
            <Text style={styles.label}>calling TurboDemo…</Text>
          ) : (
            turboResults.map(([label, value]) => (
              <View key={label} style={styles.row}>
                <Text style={styles.label}>{label}</Text>
                <Text style={styles.value}>{value}</Text>
              </View>
            ))
          )}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  background: {
    backgroundColor: '#fff',
  },
  error: {
    fontSize: 16,
    color: '#c00',
    marginTop: 12,
  },
  container: {
    padding: 24,
    gap: 8,
  },
  title: {
    fontSize: 28,
    fontWeight: '700',
    marginBottom: 4,
    color: '#000',
  },
  subtitle: {
    fontSize: 14,
    color: '#666',
    marginTop: 16,
    marginBottom: 8,
  },
  subtitleTop: {
    fontSize: 14,
    color: '#666',
    marginTop: 32,
    marginBottom: 8,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    paddingVertical: 10,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#ddd',
    gap: 12,
  },
  label: {
    fontSize: 14,
    color: '#333',
    flexShrink: 1,
  },
  value: {
    fontSize: 14,
    fontWeight: '600',
    color: '#0a7',
    flexShrink: 1,
    textAlign: 'right',
  },
});

export default App;
